"use strict";(globalThis.webpackChunkdoqumentation=globalThis.webpackChunkdoqumentation||[]).push([[7179],{15483(a,n,g){g.r(n),g.d(n,{assets:()=>e,contentTitle:()=>m,default:()=>l,frontMatter:()=>s,metadata:()=>i,toc:()=>o});const i=JSON.parse('{"id":"learning/courses/quantum-business-foundations/quantum-technology","title":"Quantum Technology","description":"Kilalanin na ang paglutas ng mga makabuluhang problema ay magsasangkot ng kombinasyon ng quantum at klasikal na mga mapagkukunan.","source":"@site/i18n/tl/docusaurus-plugin-content-docs/current/learning/courses/quantum-business-foundations/quantum-technology.mdx","sourceDirName":"learning/courses/quantum-business-foundations","slug":"/learning/courses/quantum-business-foundations/quantum-technology","permalink":"/learning/courses/quantum-business-foundations/quantum-technology","draft":false,"unlisted":false,"editUrl":"https://github.com/JanLahmann/doQumentation/tree/main/docs/learning/courses/quantum-business-foundations/quantum-technology.mdx","tags":[],"version":"current","frontMatter":{"title":"Quantum Technology","description":"Kilalanin na ang paglutas ng mga makabuluhang problema ay magsasangkot ng kombinasyon ng quantum at klasikal na mga mapagkukunan."},"sidebar":"tutorialsSidebar","previous":{"title":"Mga pangunahing kaalaman sa quantum computing","permalink":"/learning/courses/quantum-business-foundations/quantum-computing-fundamentals"},"next":{"title":"Epekto sa Negosyo","permalink":"/learning/courses/quantum-business-foundations/business-impacts"}}');var t=g(74848),u=g(28453);const s={title:"Quantum Technology",description:"Kilalanin na ang paglutas ng mga makabuluhang problema ay magsasangkot ng kombinasyon ng quantum at klasikal na mga mapagkukunan."},m="IBM Quantum technology",e={},o=[{value:"Mga layunin sa pag-aaral",id:"learning-objectives",level:2},{value:"IBM Quantum Platform",id:"ibm-quantum-platform",level:3},{value:"Qiskit Runtime",id:"qiskit-runtime",level:3},{value:"IBM superconducting quantum computers",id:"ibm-superconducting-quantum-computers",level:3},{value:"Quantum computing performance",id:"quantum-computing-performance",level:2},{value:"Pagsukat ng quantum computing performance",id:"measuring-quantum-computing-performance",level:3},{value:"Subukan ang iyong pag-unawa",id:"check-your-understanding",level:3},{value:"Ano ang susunod sa quantum computing",id:"whats-next-in-quantum-computing",level:2},{value:"Quantum utility",id:"quantum-utility",level:3},{value:"Error Correction",id:"error-correction",level:3},{value:"IBM Quantum Development Roadmap",id:"ibm-quantum-development-roadmap",level:3},{value:"5k challenge",id:"5k-challenge",level:3},{value:"Quantum-centric supercomputers",id:"quantum-centric-supercomputers",level:3},{value:"Mga pangunahing aral",id:"key-takeaways",level:2}];function r(a){const n={a:"a",em:"em",h1:"h1",h2:"h2",h3:"h3",header:"header",img:"img",li:"li",p:"p",strong:"strong",ul:"ul",...(0,u.R)(),...a.components},{Details:i,IBMVideo:s}=n;return i||p("Details",!0),s||p("IBMVideo",!0),(0,t.jsxs)(t.Fragment,{children:["\n","\n",(0,t.jsx)(n.header,{children:(0,t.jsx)(n.h1,{id:"ibm-quantum-technology",children:"IBM Quantum technology"})}),"\n",(0,t.jsx)(n.p,{children:"Ang fleet ng IBM\xae quantum computers, na lahat ay may hindi bababa sa 127 qubits, ang pinakamalaki sa buong mundo. Ang mga quantum computer na ito ay gumagamit ng superconducting transmon qubits, na hindi lamang ang uri ng qubit, ngunit maraming pakinabang. Ang pagsasama ng aming world-class na quantum computers kasama ang Qiskit ay nagbibigay-daan sa aming mga user na tuklasin kung paano magiging kapaki-pakinabang ang quantum computing sa mundo, ngayon. Ang mga kasosyo sa industriya at mga mananaliksik ay gumagamit ng IBM Quantum\xae technology upang tuklasin ang mga makabuluhang computation at mga realistikong aplikasyon. Tuklasin natin ang saklaw ng mga programa at serbisyo na inaalok ng IBM Quantum sa mga kasosyo."}),"\n",(0,t.jsx)(n.p,{children:"Kung ikaw ay bahagi ng isang institusyon na miyembro ng IBM Quantum Network, tiyaking makipag-ugnayan sa quantum computing group ng iyong institusyon upang malaman kung anong mga benepisyo ang maaari mong ma-access."}),"\n",(0,t.jsx)(n.h2,{id:"learning-objectives",children:"Mga layunin sa pag-aaral"}),"\n",(0,t.jsx)(n.p,{children:"Sa pagtatapos ng modyul na ito, dapat ay magagawa mo ang:"}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsx)(n.li,{children:"Kilalanin na ang paglutas ng mga makabuluhang problema ay magsasangkot ng kombinasyon ng quantum at klasikal na mga mapagkukunan."}),"\n",(0,t.jsx)(n.li,{children:"Tukuyin ang hardware, software, at mga serbisyong available upang malutas ang mga makabuluhang problema."}),"\n",(0,t.jsx)(n.li,{children:"Ilarawan kung paano sukatin ang performance ng quantum computing, kabilang ang scale, quality, at speed."}),"\n"]}),"\n",(0,t.jsx)(n.h3,{id:"ibm-quantum-platform",children:"IBM Quantum Platform"}),"\n",(0,t.jsx)(n.p,{children:"Ang IBM Quantum Platform ay nagbibigay ng isang suite ng quantum computing tools na pinagsasama ang lahat ng research at development resources na kailangan ng mga user para makagawa ng mahusay na trabaho, sa isang lugar. Maaaring lumikha ng account at mag-sign in ang mga user para ma-access ang mga IBM quantum computer, tingnan ang mga detalye ng computer, subaybayan ang mga workload, at ma-access ang mga enablement material sa Documentation at Learning."}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsxs)(n.li,{children:["Ang ",(0,t.jsx)(n.a,{href:"https://quantum.cloud.ibm.com/",children:"Home page"})," ay nagsisilbing pangunahing panimulang punto para sa product ecosystem, kung saan maaaring makuha ng mga user ang kanilang mga API key, tingnan ang buod ng kanilang mga instance at impormasyon sa paggamit, tingnan ang mga kamakailang detalye ng trabaho, at ma-access ang mga kapaki-pakinabang na link sa iba pang lugar sa platform."]}),"\n",(0,t.jsxs)(n.li,{children:["Ang ",(0,t.jsx)(n.a,{href:"/docs",children:"Documentation"})," ay nag-iipon ng Qiskit documentation, service documentation, at API reference information sa isang lokasyon, na nakaorganisa sa paraang sumusuporta sa natural na daloy ng trabaho ng mga user."]}),"\n",(0,t.jsxs)(n.li,{children:["Ang ",(0,t.jsx)(n.a,{href:"/learning",children:"Learning"})," ang tahanan ng mga educational material kabilang ang mga kurso at teaching module, at ang interactive circuit Composer (paparating na). Ang kombinasyong graphical at code editor na ito ay nagbibigay-daan sa mga user na mag-prototype, mag-simulate, at mag-debug ng mga circuit nang biswal, at pagkatapos ay patakbuhin ang mga ito sa mga IBM quantum computer."]}),"\n"]}),"\n",(0,t.jsx)(n.h3,{id:"qiskit-runtime",children:"Qiskit Runtime"}),"\n",(0,t.jsx)(n.p,{children:"Ang Qiskit Runtime ay isang portable, secure, containerized na arkitektura na nagpapatakbo ng mga quantum program sa isang klasikal na computing unit na malapit na naka-integrate sa quantum processor. Nagbibigay-daan ang Qiskit Runtime para maging bahagi ng quantum computer sa anumang computing environment upang mapabilis ang computation \u2014 katulad ng isang graphics processing unit (GPU) \u2014 at pinamamahalaan ang job orchestration at paglilipat ng data sa quantum processing unit, na nagpapalaki ng kahusayan."}),"\n",(0,t.jsx)(n.p,{children:"Ginagawa ng Qiskit at Qiskit Runtime na simple ang mabilis na pag-orchestrate ng mga program sa mga compute resource sa cloud. Gumagawa ang IBM ng middleware para sa quantum upang mapakinabangan ang performance ng mga quantum application na tumatakbo sa paralelisadong, cloud-based, quantum at klasikal na computational resources. Kasama sa middleware na ito ang circuit knitting toolbox at ang aming quantum serverless architecture."}),"\n",(0,t.jsxs)(n.p,{children:["Ang ",(0,t.jsx)(n.a,{href:"https://docs.quantum.ibm.com/api/qiskit-addon-cutting",children:"circuit cutting Qiskit addon"})," ay nagbibigay-daan sa mga developer na putulin ang malalaking circuit sa mas maliliit na circuit na angkop sa mga kasalukuyang quantum computer. Gumagamit ang circuit knitting ng klasikal na computation upang panagutan ang ilang bahagi ng computational burden ng isang quantum circuit upang malagpasan ang magagawa natin sa alinman sa dalawa nang mag-isa. Ang mga karagdagang tool ay tumutulong na muling buuin ang mga circuit gamit ang klasikal na mga mapagkukunan at pinagsasama ang mga panghuling resulta."]}),"\n",(0,t.jsxs)(n.p,{children:["Ang ",(0,t.jsx)(n.a,{href:"/guides/serverless",children:"Quantum Serverless"})," ay isang multi-cloud orchestration toolkit upang ikonekta ang elastic classical resources sa IBM Qiskit Runtime service. Nagbibigay-daan ang Quantum Serverless sa mga developer na mag-focus sa code, sa halip na sa resource provisioning."]}),"\n",(0,t.jsx)(n.h3,{id:"ibm-superconducting-quantum-computers",children:"IBM superconducting quantum computers"}),"\n",(0,t.jsxs)(n.p,{children:["Ang mga IBM quantum processor ay gumagamit ng pisikal na uri ng qubit na tinatawag na ",(0,t.jsx)(n.strong,{children:"superconducting transmon qubit"}),", na gawa mula sa superconducting materials na nakalagay sa isang silicon substrate. Ang ibang mga quantum processor ay maaaring gumamit ng photonic qubits, na gawa mula sa mga solong photon ng liwanag, o trapped-ion qubits, na nag-iimbak ng impormasyon sa mga charged atomic particle. Upang mapadali ang daloy ng kuryente, kailangang mapanatili ang mga superconducting qubit sa napakababang temperatura \u2014 malapit sa absolute zero."]}),"\n",(0,t.jsx)(n.p,{children:(0,t.jsx)(n.img,{alt:"IBM 127-qubit processor",src:g(60794).A+"",width:"450",height:"450"})}),"\n",(0,t.jsx)(n.p,{children:(0,t.jsx)(n.em,{children:"IBM 127-qubit processor"})}),"\n",(0,t.jsx)(n.h2,{id:"quantum-computing-performance",children:"Quantum computing performance"}),"\n",(0,t.jsx)(n.h3,{id:"measuring-quantum-computing-performance",children:"Pagsukat ng quantum computing performance"}),"\n",(0,t.jsx)(n.p,{children:"Ang isang universal fault-tolerant quantum computer ang malaking hamon ng quantum computing. Ito ay isang device na makakapag-perform nang tama ng mga universal quantum operation gamit ang hindi mapagkakatiwalaang mga komponente. Ang mga quantum computer ngayon ay hindi fault-tolerant."}),"\n",(0,t.jsx)(n.p,{children:"Upang ikumpara ang mga quantum computer sa isa't isa, hindi sapat ang bilang ng qubit. Maraming iba pang detalye ang dapat isaalang-alang, tulad ng mga error rate at kung paano naka-wire ang sistema. May apat na pangunahing sukatan para sa pagsukat ng quantum computing performance:"}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Scale"})," \u2014 Sinusukat sa pamamagitan ng ",(0,t.jsx)(n.strong,{children:"bilang ng mga qubit"}),", na nagpapakita ng dami ng impormasyon na maaari nating i-encode sa quantum computer."]}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Quality"})," \u2014 Sinusukat sa pamamagitan ng ",(0,t.jsx)(n.strong,{children:"Quantum Volume"}),", na nagpapakita ng kalidad ng mga circuit at kung gaano katumpak ang pagpapatupad ng mga circuit sa hardware."]}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Speed"})," \u2014 Sinusukat sa pamamagitan ng ",(0,t.jsx)(n.strong,{children:"CLOPS (circuit Layer Operations Per Second)"}),", na nagpapakita ng ilang circuit ang makakapatakbo sa hardware sa isang takdang panahon."]}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Layer Fidelity"})," \u2014 Sinusukat sa pamamagitan ng ",(0,t.jsx)(n.strong,{children:"EPLG (Errors Per Layered gate)"}),", na naglalarawan kung paano nagaganap ang mga error kapag isinasagawa ang mga operasyon sa mga qubit."]}),"\n"]}),"\n",(0,t.jsxs)(n.p,{children:["Para sa mas detalyadong paglalarawan ng ilan sa mga sukatan sa itaas, tingnan ang ",(0,t.jsx)(n.a,{href:"https://www.ibm.com/quantum/blog/quantum-metric-layer-fidelity",children:"artikulong ito"})," sa IBM Research Blog. Ang bawat yugto sa pag-adopt ng quantum computing sa industriya ay pinapatakbo ng pagtaas ng Quantum Volume, na kinakalkula gamit ang iba't ibang parameter tulad ng lapad ng circuit, koneksyon ng qubit, at mga error rate."]}),"\n",(0,t.jsx)(n.p,{children:"Ang teknikal na kahulugan ng Quantum Volume ay mahirap ipaliwanag nang walang mga equation.\nIpinaliliwanag ni Dario Gil, Direktor ng Research sa IBM:"}),"\n",(0,t.jsx)(s,{id:"133345140",title:"Dario Gil explains the concept of quantum volume. In particular he explains how and why it depends on both qubit count and error rates."}),"\n",(0,t.jsx)(n.p,{children:"Upang mas maunawaan ang Quantum Volume, isaalang-alang ang sumusunod na kawili-wiling paghahambing. Tinatakpan ng seksyon sa ibaba ang oras, espasyo, at mga error rate sa mga tuntunin ng pagsasagawa ng isang paglilibot sa New York City."}),"\n",(0,t.jsx)(n.p,{children:(0,t.jsx)(n.strong,{children:"Pag-tour ng mga estado ng Quantum Volume"})}),"\n",(0,t.jsxs)(n.p,{children:["Inilalarawan ng Quantum Volume ang pinakamalaking quantum computational space na maaaring tuklasin ng isang quantum computer, kung saan ang volume ng quantum space ay 2",(0,t.jsx)("sup",{children:"N"}),', na si N ang bilang ng mga qubit, iyon ay, ang karaniwang dimensyon ng state space. Sadya naming ginagamit ang salitang "espasyo" dito dahil kapag nabanggit na natin ang espasyo, madaling isipin ang isang volume.']}),"\n",(0,t.jsx)(n.p,{children:"Ang salik na naglilimita sa pagtuklas na ito ay ang error rate. Ang error rate ay maaaring ikatumbas sa dami ng oras na pinahihintulutan tayong tuklasin ang espasyo. Mas maraming error ay nangangahulugang mas kaunting oras para magtuklas. Habang mas malaki ang computational space, mas matagal itong ganap na tuklasin, kaya kailangan natin ng isang quantum computer na may mas maliit na error rate."}),"\n",(0,t.jsx)(n.p,{children:"Isaalang-alang ang isang turista na nagliliwaliw sa New York City. Nais ng turista na tuklasin ang buong lungsod, ibig sabihin gusto ng turista ng tourist volume na katumbas ng NYC. Kung bibigyan natin ang turista ng isang araw lamang, wala itong paraan upang tuklasin ang ganoon kalaking espasyo, kaya hindi makukuha ng turista ang nais na tourist volume. Ngunit kung bibigyan natin ang turista ng tatlong araw, malamang na mabibisita niya ang lahat ng nangungunang lugar at makukuha ang kinakailangang tourist volume ng NYC."}),"\n",(0,t.jsx)(n.p,{children:"Ngayon, paano kung bibigyan natin ang turista ng mas maraming oras ngunit nililimitahan pa rin ang espasyo sa NYC? Sa ibang salita, paano kung panatilihin nating pareho ang bilang ng mga qubit ngunit babawasan ang error rate? Hindi na magiging kapaki-pakinabang ito sa turista dahil natuklas na niya ang lungsod at paulit-ulit na lang siyang dumarating sa parehong mga lugar. Nananatiling pareho ang tourist volume. Sa halip, kapag may mas maraming oras, mas matalino para sa turista na palawakin ang bilang ng mga tourist spot na bibisitahin."}),"\n",(0,t.jsx)(n.p,{children:"O, ipagpalagay nating nakatakda ang oras sa tatlong araw ngunit nagpasya ang turista na subukang tuklasin ang buong NYC at Long Island? Sa ibang salita, paano kung ayusin natin ang error rate ngunit magdagdag ng mas maraming qubit? Muli, ang tourist volume ay nananatiling katumbas ng NYC dahil hindi kayang tuklasin ng turista ang mas malaking espasyo sa takdang oras. Kaya, upang maging mas mahusay na turista at makamit ang mas malaking tourist volume, kailangang sabay na palakihin ang espasyong nililiwaliw at ang dami ng oras na pinahihintulutan ang turista na magtuklas."}),"\n",(0,t.jsx)(n.p,{children:"Sa parehong paraan, ang pagbuo ng mas mahusay na mga quantum computer na nakakamit ng mas malaking Quantum Volume ay nangangailangan ng sabay na pagpapalaki ng quantum computational space (bilang ng mga qubit) habang binabawasan ang error rate (pinapataas ang dami ng oras na maaaring tumakbo ang algorithm). Halimbawa, sa pamamagitan ng mga pagsulong sa tunable coupling architectures, dinoblo ng IBM ang quantum volume nang dalawang beses sa loob ng isang taon lamang!"}),"\n",(0,t.jsx)(n.p,{children:(0,t.jsx)(n.img,{src:"/learning/images/courses/quantum-business-foundations/quantum-technology/QV.avif",alt:"Quantum Volume"})}),"\n",(0,t.jsx)(n.p,{children:"Ngunit habang umuunlad ang quantum computing, mas pinapahalagahan natin ang kapaki-pakinabang na trabaho na magagawa ng ating mga quantum computer sa makatwirang tagal ng oras. Kung sinusukat natin ang scale sa bilang ng mga qubit, at quality sa quantum volume, ang quantum processing speed ang sukatan ng kapaki-pakinabang na trabaho na magagawa ng mga qubit na iyon sa makatwirang tagal ng oras. Tinukoy natin ito bilang ang bilang ng mga primitive circuit na maaaring maproseso sa isang segundo. Katulad ito ng FLOPS sa klasikal na computing \u2014 ang bilang ng floating point operations bawat segundo. Ang pagpapabuti ng QPU speed ang susi sa praktikal na quantum computing. Tulad ng klasikal na computer programming, ang quantum programming ay nangangailangan ng pagpapatakbo ng maraming circuit. Ang makatwirang QPU speed ay magbibigay-daan sa mga user na isama ang quantum computing bilang bahagi ng kanilang mga workflow."}),"\n",(0,t.jsx)(n.h3,{id:"check-your-understanding",children:"Subukan ang iyong pag-unawa"}),"\n",(0,t.jsx)(n.p,{children:"Basahin ang tanong sa ibaba, isipin ang iyong sagot, pagkatapos ay i-click ang tatsulok upang ipakita ang solusyon."}),"\n",(0,t.jsxs)(i,{children:[(0,t.jsx)("summary",{children:(0,t.jsx)(n.p,{children:"Tama o mali: Ang Quantum Volume ay tumutukoy sa laki ng mga cryogenic refrigerator na nagtataglay ng mga IBM quantum computer."})}),(0,t.jsx)(n.p,{children:"Mali. Ang Quantum Volume ay isang solong numero na nilayong buuin ang performance ng mga quantum computer ngayon."})]}),"\n",(0,t.jsx)(n.h2,{id:"whats-next-in-quantum-computing",children:"Ano ang susunod sa quantum computing"}),"\n",(0,t.jsx)(n.p,{children:"Ang mga quantum computer ngayon, at ang mga inaasahan para sa nakikitang hinaharap, ay maingay. Ibig sabihin ay sensitibo sila sa mga pagkagambala sa kapaligiran na maaaring makaapekto sa katumpakan ng mga resulta. Tulad ng klasikal na computing na umunlad sa pamamagitan ng modular na scaling ng mga processor, mahusay na computation, at parallelization, nakikita natin ang quantum computing na umuunlad upang matupad ang buong potensyal nito. Habang nagsisikap tayo tungo sa mga ganap na fault-tolerant na quantum computer, nais nating malutas ang mga kapaki-pakinabang na problema gamit ang hardware at software na mayroon tayo ngayon."}),"\n",(0,t.jsx)(n.h3,{id:"quantum-utility",children:"Quantum utility"}),"\n",(0,t.jsx)(n.p,{children:"Ang IBM Quantum at ang University of California, Berkeley ay nagpresenta ng katibayan na ang mga quantum computer ay makakapagbigay ng halaga nang mas maaga kaysa sa inaasahan salamat sa mga pagsulong sa IBM Quantum hardware at mga pamamaraan ng error mitigation. Higit pa sa isang patunay ng konsepto, naghatid tayo ng mga resulta na tumpak na sapat upang maging kapaki-pakinabang. Ang modelo ng computation na aming tinuklas sa gawaing ito ay isang pangunahing aspeto ng maraming algorithm na dinisenyo para sa mga near-term quantum computer."}),"\n",(0,t.jsx)(n.p,{children:"Ang feedback loop sa pagitan ng quantum at klasikal ay susi sa pagsulong ng mga quantum technology. Sa pagtuon sa quantum utility, ginagamit natin ang quantum upang suriin ang mga kumplikadong problema na humahamon sa mga kasalukuyang high-performance compute framework, pagkatapos ay sinusuri ang mga resulta nang klasikal. Ang patuloy na pagpapalitan na ito ng quantum na nagpapatakbo ng kumplikadong circuit at ng mga klasikal na computer na nagbe-verify ng mga quantum na resulta ay magpapabuti sa parehong computational domain at magbibigay ng kumpiyansa sa mga user sa mga kakayahan ng mga near-term quantum computer."}),"\n",(0,t.jsx)(s,{id:"134056420",title:"This video outlines how noisy quantum computers use error mitigation to out-perform brute force classical methods on an example problem."}),"\n",(0,t.jsxs)(i,{children:[(0,t.jsx)("summary",{children:(0,t.jsx)(n.p,{children:"Opsyonal na pagbabasa \u2014 i-click ang tatsulok upang matuto nang higit pa tungkol sa eksperimento"})}),(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsx)(n.p,{children:"Sa eksperimentong ito, ginamit namin ang lahat ng 127 qubit ng aming IBM Quantum Eagle processor upang i-simulate ang nagbabagong gawi ng isang sistema na natural na naimamapa sa isang quantum computer, na tinatawag na quantum Ising model. Ang mga Ising model ay mga simplipikasyon ng kalikasan na kumakatawan sa mga nakikipag-ugnayan na atom bilang isang lattice ng nakikipag-ugnayan na quantum two-choice system sa isang energy field. Ang mga sistemang ito ay kamukha ng mga two-state qubit na bumubuo sa ating mga quantum computer, na ginagawa silang angkop para sa pagsubok ng mga kakayahan ng ating mga pamamaraan. Ginamit namin ang ZNE upang subukang tumpak na kalkulahin ang isang katangian ng sistema na tinatawag nitong expectation value \u2014 mahalagang isang weighted average ng mga posibleng resulta ng circuit."}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsx)(n.p,{children:"Sabay-sabay, sinubukan ng Berkeley team na i-simulate ang parehong sistema gamit ang tensor network methods sa tulong ng mga advanced na supercomputer na matatagpuan sa Lawrence Berkeley National Lab's National Energy Research Scientific Computing Center (NERSC) at sa Purdue University."}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsx)(n.p,{children:"Patuloy na sumasang-ayon ang mga quantum method sa mga eksaktong pamamaraan. Ngunit kalaunan, ang mga klasikal na approximation method ay nagsimulang humina habang tumaas ang kahirapan."}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsx)(n.p,{children:"Sa wakas, hiniling namin sa parehong computer na magsagawa ng mga kalkulasyon na higit pa sa kung ano ang maaaring kalkulahin nang eksakto \u2014 at nagbalik ang quantum computer ng isang sagot na mas pinaniniwalaan naming tama. At kahit hindi natin mapatunayan kung tama ba talaga ang sagot na iyon, ang tagumpay ng Eagle sa mga nakaraang takbo ng eksperimento ay nagbigay sa amin ng kumpiyansa na tama ang mga ito."}),"\n"]}),"\n"]})]}),"\n",(0,t.jsx)(n.h3,{id:"error-correction",children:"Error Correction"}),"\n",(0,t.jsx)(n.p,{children:"Ang error correction ay isang pangunahing larangan ng pananaliksik sa loob ng maraming dekada. Ngunit sa karamihan ng panahong iyon, ang mga teoretikal na pamamaraan ng error correction ay hindi praktikal na maipatupad sa mga tunay na quantum computer, kadalasang dahil sa napakalaking bilang ng mga qubit na kailangan. Sa katunayan, maraming eksperto ang nanghuhula na ang praktikal na fault tolerant quantum computing (FTQC) ay mangangailangan ng milyun-milyong pisikal na qubit. Ngunit sa isang kamakailang papel na inilathala sa cover ng Nature, ipinakilala ng mga mananaliksik mula sa IBM ang isang bagong code, na tinatawag nating Gross code, na lumalagpas sa limitasyong iyon."}),"\n",(0,t.jsxs)(n.p,{children:["Inilalarawan ng papel na ",(0,t.jsx)(n.a,{href:"https://www.nature.com/articles/s41586-024-07107-7",children:"High-threshold and low-overhead fault-tolerant quantum memory"})," ang bagong quantum error-correcting code na halos 10 beses na mas mahusay kaysa sa mga nakaraang pamamaraan sa pagprotekta ng mga delikadong quantum data mula sa pag-iipon ng mga error. Upang isaalang-alang kung gaano natin nalalapit ang simula ng error correction, isaalang-alang na gamit ang Gross code, maaari mong protektahan ang 12 logical qubit para sa halos isang milyong siklo ng mga pagsusuri ng error gamit ang 288 qubit."]}),"\n",(0,t.jsx)(n.p,{children:"Hindi inaasahan na ang error correction ay biglang papalitan ang error mitigation at error suppression. Sa halip, sa susunod na ilang taon, ang error mitigation at suppression ay magpapatuloy na gumanap ng mahalagang papel, kasabay ng patuloy na pagtaas ng bilang ng mga error-corrected qubit."}),"\n",(0,t.jsx)(n.h3,{id:"ibm-quantum-development-roadmap",children:"IBM Quantum Development Roadmap"}),"\n",(0,t.jsx)(n.p,{children:"Nasa panahon na tayo ng quantum utility. Ibig sabihin, mas mahusay na ang mga quantum computer kaysa sa mga klasikal na computer pagdating sa quantum computing, at maaari itong gamitin ng aming mga user upang tuklasin ang mga bagong algorithm at maghanap ng mga quantum advantage. Ang aming roadmap ay nagbabalangkas ng aming mga makasaysayang milestone at mga plano upang makamit ang near-term quantum advantage sa 2026."}),"\n",(0,t.jsxs)(n.p,{children:["Sa 2029, maihahatid namin ang Starling \u2014 isang large-scale fault-tolerant quantum computer na kayang magpatakbo ng mga quantum circuit na binubuo ng 100 milyong quantum gate sa 200 logical qubit. Binubuo namin ang sistemang ito ngayon sa aming makasaysayang pasilidad sa Poughkeepsie, New York. Matuto nang higit pa tungkol sa aming pag-unlad sa ",(0,t.jsx)(n.a,{href:"http://www.ibm.com/downloads/documents/us-en/131cf87ab63319bf",children:"Guided Roadmap PDF."})]}),"\n",(0,t.jsx)(n.p,{children:(0,t.jsx)(n.img,{alt:"Development Roadmap",src:g(80305).A+"",width:"1920",height:"1080"})}),"\n",(0,t.jsxs)(n.p,{children:["Magbasa nang higit pa tungkol sa IBM Quantum development roadmap ",(0,t.jsx)(n.a,{href:"https://www.ibm.com/quantum/roadmap",children:"dito"}),"."]}),"\n",(0,t.jsx)(n.h3,{id:"5k-challenge",children:"5k challenge"}),"\n",(0,t.jsx)(n.p,{children:'Nagtatrabaho ang IBM kasama ang quantum research community upang mahanap ang mga potensyal na use case na maaaring makinabang mula sa quantum computing. Nagbibigay kami ng mga lalong makapangyarihang tool upang matuklas ng mga user ang mga mahalagang problema sa quantum. Noong 2024, naglabas kami ng isang tool na kayang kalkulahin ang mga walang kinikilingang observable ng mahahaba, mataas na kalidad na circuit. Ang paghahanap ng kung ano ang magagawa sa kombinasyong ito ng 100+ qubit at malalim na circuit ay minsan ay tinawag na "100x100 challenge". Ngunit ang tiyak na bilang ng mga qubit at lalim sa bawat isa ay hindi gaanong mahalaga kaysa sa pagsasamantala sa kapangyarihan ng kombinasyon. Isipin kung ano ang posible sa 5,000 quantum gate sa isang solong computation. Maaaring magpatakbo ang mga user ng mga quantum circuit na may kumplikasyon at runtime na lumalagpas sa mga kakayahan ng pinakamahusay na mga klasikal na computer ngayon. Nasasabik kaming makita kung ano ang itatayo ng quantum community upang matulungan tayong samantalahin ang kapangyarihan ng quantum at malutas ang mga mahahalagang problema.'}),"\n",(0,t.jsx)(n.h3,{id:"quantum-centric-supercomputers",children:"Quantum-centric supercomputers"}),"\n",(0,t.jsx)(n.p,{children:"Ang paglampas sa mga single chip processor ang susi sa paglutas ng mga problema sa malaking sukat. Noong 2024, ipinakilala namin ang Crossbill, ang unang single processor na gawa mula sa maraming chip. Ito ang unang hakbang upang manguna sa isang bagong panahon ng scaling, na nagbibigay ng malinaw na landas patungo sa 100,000 qubit at higit pa sa quantum-centric supercomputing. Ito ay isang modular computing architecture na nagbibigay-daan sa scaling. Pinagsasama nito ang quantum communication at computation upang mapataas ang computational capacity, habang gumagamit ng hybrid cloud middleware upang maayos na isama ang mga quantum at klasikal na workflow."}),"\n",(0,t.jsx)(n.p,{children:"Ang paglutas ng pinaka-kumplikadong mga problema sa mundo ay mangangailangan ng kombinasyon ng klasikal at quantum na mga mapagkukunan. Bukod pa rito, depende ito sa patuloy na pakikipagtulungan sa pagitan ng industriya at akademiya."}),"\n",(0,t.jsx)(n.h2,{id:"key-takeaways",children:"Mga pangunahing aral"}),"\n",(0,t.jsx)(n.p,{children:"Maaari mong isaisip ang mga pangunahing aral na ito:"}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsx)(n.li,{children:"Ang mga quantum computer ngayon ay hindi fault tolerant."}),"\n",(0,t.jsx)(n.li,{children:"Ang Quantum Volume ay isang holistikong sukatan ng kung gaano kahusay ang isang quantum computer. Habang mas mataas ang Quantum Volume, mas magaling. Ang pag-usap lamang tungkol sa bilang ng qubit ay mapanlinlang."}),"\n",(0,t.jsx)(n.li,{children:"Upang masukat ang performance ng mga quantum computer, may apat na pangunahing sukatan: scale, quality, speed, at layer fidelity."}),"\n",(0,t.jsx)(n.li,{children:"Ang isang pinagsamang eksperimento ng IBM Quantum-UC Berkeley ay nagpresenta ng katibayan na ang mga IBM quantum computer ay naghahatid ng maaasahan, tumpak na mga resulta para sa mga mapanghamon na problema sa simulation sa sukat na 127 qubit."}),"\n",(0,t.jsx)(n.li,{children:"Ang quantum-centric supercomputing ay nangangahulugang tratuhin ang quantum bilang isang piraso ng mas malawak na HPC paradigm kung saan ang klasikal at quantum ay gumaganap bilang isang computational unit."}),"\n"]})]})}function l(a={}){const{wrapper:n}={...(0,u.R)(),...a.components};return n?(0,t.jsx)(n,{...a,children:(0,t.jsx)(r,{...a})}):r(a)}function p(a,n){throw new Error("Expected "+(n?"component":"object")+" `"+a+"` to be defined: you likely forgot to import, pass, or provide it.")}},60794(a,n,g){g.d(n,{A:()=>i});const i=g.p+"assets/images/127qubit-processer-5f4e07dd161a5396ac24b1af43f9999a.avif"},80305(a,n,g){g.d(n,{A:()=>i});const i=g.p+"assets/images/IBM-Quantum-Development-and-Innovation-Roadmap-2025-f5804f9bec56cfc9744c8755f6d3a0a5.svg"},28453(a,n,g){g.d(n,{R:()=>s,x:()=>m});var i=g(96540);const t={},u=i.createContext(t);function s(a){const n=i.useContext(u);return i.useMemo(function(){return"function"==typeof a?a(n):{...n,...a}},[n,a])}function m(a){let n;return n=a.disableParentContext?"function"==typeof a.components?a.components(t):a.components||t:s(a.components),i.createElement(u.Provider,{value:n},a.children)}}}]);